import React from 'react'
import {
  LayoutDashboard,
  Receipt,
  TrendingUp,
  TrendingDown,
  LogOut,
  Sparkles
} from 'lucide-react'

function Navigation({active, setActive}) {
    const menuItems = [
        {
            id: 1,
            title: 'Dashboard',
            icon: LayoutDashboard,
            link: '/dashboard'
        },
        {
            id: 2,
            title: "Transactions",
            icon: Receipt,
            link: "/transactions",
        },
        {
            id: 3,
            title: "Income",
            icon: TrendingUp,
            link: "/income",
        },
        {
            id: 4,
            title: "Expenses",
            icon: TrendingDown,
            link: "/expenses",
        },
    ]

    return (
        <nav className="w-[220px] h-full flex flex-col bg-white border-r border-gray-200">
            {/* Header */}
            <div className="p-6 border-b border-gray-100">
                <div className="flex items-center space-x-3">
                    <div className="w-10 h-10 bg-gradient-to-br from-blue-500 to-purple-600 rounded-full flex items-center justify-center">
                        <span className="text-white font-semibold text-sm">CS</span>
                    </div>
                    <div>
                        <h2 className="text-sm font-medium text-gray-900">Chandra Shekar</h2>
                        <p className="text-xs text-gray-500">Your Money</p>
                    </div>
                </div>
            </div>

            {/* Menu Items */}
            <div className="flex-1 py-6">
                <ul className="space-y-1 px-3">
                    {menuItems.map((item) => {
                        const Icon = item.icon
                        const isActive = active === item.id

                        return (
                            <li key={item.id}>
                                <button
                                    onClick={() => setActive(item.id)}
                                    className={`
                                        w-full flex items-center space-x-3 px-3 py-2.5 text-left
                                        transition-all duration-200 rounded-lg relative
                                        ${isActive
                                            ? 'text-blue-600 bg-blue-50'
                                            : 'text-gray-600 hover:text-gray-900 hover:bg-gray-50'
                                        }
                                    `}
                                >
                                    {/* Active indicator line */}
                                    {isActive && (
                                        <div className="absolute left-0 top-0 bottom-0 w-0.5 bg-blue-600 rounded-r-full" />
                                    )}

                                    <Icon
                                        size={18}
                                        className={`transition-colors duration-200 ${
                                            isActive ? 'text-blue-600' : 'text-gray-400'
                                        }`}
                                    />
                                    <span className="text-sm font-medium">{item.title}</span>
                                </button>
                            </li>
                        )
                    })}
                </ul>
            </div>

            {/* Footer */}
            <div className="p-6 border-t border-gray-100">
                <div className="flex items-center justify-between">
                    <div className="flex items-center space-x-2">
                        <Sparkles size={14} className="text-purple-500" />
                        <span className="text-xs text-gray-500 font-mono">AI-enhanced</span>
                    </div>
                    <button className="flex items-center space-x-2 text-gray-500 hover:text-gray-700 transition-colors duration-200">
                        <LogOut size={16} />
                        <span className="text-sm">Sign out</span>
                    </button>
                </div>
            </div>
        </nav>
    )
}

export default Navigation
